<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain;

use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetUidVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetThemeVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor\ThemeAssetThemeAccessor;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetCodeVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor\ThemeAssetCodeAccessor;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetTypeVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor\ThemeAssetTypeAccessor;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetContentVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor\ThemeAssetContentAccessor;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetEnabledVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor\ThemeAssetEnabledAccessor;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetVersionVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor\ThemeAssetVersionAccessor;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Formula\EnabledCalculator;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Event\ThemeAssetCreateEvent;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Event\ThemeAssetUpdateEvent;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Event\ThemeAssetDeleteEvent;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Event\ThemeAssetEnableEvent;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Event\ThemeAssetDisableEvent;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Shared\Connector\FileStorage\FileStorageInterface;
use Civi\Lughauth\Shared\Connector\FileStorage\FileStoreKey;

class ThemeAsset extends ThemeAssetRef
{
    use ThemeAssetThemeAccessor;
    use ThemeAssetCodeAccessor;
    use ThemeAssetTypeAccessor;
    use ThemeAssetContentAccessor;
    use ThemeAssetEnabledAccessor;
    use ThemeAssetVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        ThemeAssetUidVO|string $uid,
        ThemeAssetThemeVO|ThemeRef $theme,
        ThemeAssetCodeVO|string $code,
        ThemeAssetTypeVO|string $type,
        ThemeAssetContentVO|string $content,
        ThemeAssetEnabledVO|bool|null $enabled = null,
        ThemeAssetVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_theme = ThemeAssetThemeVO::from($theme);
        $this->_code = ThemeAssetCodeVO::from($code);
        $this->_type = ThemeAssetTypeVO::from($type);
        $this->_content = ThemeAssetContentVO::from($content);
        $this->_enabled = null === $enabled ? ThemeAssetEnabledVO::empty() : ThemeAssetEnabledVO::from($enabled);
        $this->_version = null === $version ? ThemeAssetVersionVO::empty() : ThemeAssetVersionVO::from($version);
    }
    public function replace(ThemeAssetAttributes $values): ThemeAsset
    {
        $value = clone $this;
        $value->_theme = $values->getThemeOrCurrent($this->_theme);
        $value->_code = $values->getCodeOrCurrent($this->_code);
        $value->_type = $values->getTypeOrCurrent($this->_type);
        $value->_content = $values->getContentOrCurrent($this->_content);
        $value->_enabled = $values->getEnabledOrCurrent($this->_enabled);
        $value->_version = $values->getVersionOrCurrent($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'enabled'];
    }
    public static function create(ThemeAssetAttributes $values): ThemeAsset
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled());
        $value = $calculated->createNewInstance();
        $value->recordedEvents[] = new ThemeAssetCreateEvent($value);
        return $value;
    }
    public function update(ThemeAssetAttributes $values): ThemeAsset
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new ThemeAssetUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): ThemeAsset
    {
        $value = clone $this;
        $value->recordedEvents[] = new ThemeAssetDeleteEvent($value);
        return $value;
    }
    public function commitContentWith(FileStorageInterface $store): void
    {
        $key = $store->commitContent(new FileStoreKey($this->getContent()));
        $this->_content = ThemeAssetContentVO::fromStored($key->key);
    }
    public function enable(): ThemeAsset
    {
        $value = clone $this;
        $value->_enabled = ThemeAssetEnabledVO::from(true);
        $value->recordedEvents[] = new ThemeAssetEnableEvent($value, original: $this);
        return $value;
    }
    public function disable(): ThemeAsset
    {
        $value = clone $this;
        $value->_enabled = ThemeAssetEnabledVO::from(false);
        $value->recordedEvents[] = new ThemeAssetDisableEvent($value, original: $this);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['theme'] = [ '$ref' => $this->getTheme()->uid() ];
        $data['code'] = $this->getCode();
        $data['type'] = $this->getType();
        $data['enabled'] = $this->isEnabled();
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): ThemeAssetAttributes
    {
        return (new ThemeAssetAttributes())
          ->uid($this->uid())
          ->theme($this->_theme)
          ->code($this->_code)
          ->type($this->_type)
          ->content($this->_content)
          ->enabled($this->_enabled)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
